import React, { useState, useEffect } from 'react';
import {
  Container,
  Paper,
  Typography,
  Box,
  Alert,
  Button,
  CircularProgress,
} from '@mui/material';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { authAPI } from '../services/api';

const VerifyEmail = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [email, setEmail] = useState('');

  useEffect(() => {
    const verifyEmail = async () => {
      const token = searchParams.get('token');
      
      console.log('🔗 Token from URL:', token);
      
      if (!token) {
        setError('Invalid verification link. No token provided.');
        setLoading(false);
        return;
      }

      try {
        console.log('📧 Sending verification request with token:', token);
        
        // Send just the token string directly
        const response = await authAPI.verifyEmail(token);
        
        console.log('✅ Verification response:', response.data);
        
        setMessage(response.data.message);
        setEmail(response.data.email);
        setLoading(false);
        
        // Redirect to login after 3 seconds
        setTimeout(() => {
          navigate('/login');
        }, 3000);
      } catch (error) {
        console.error('❌ Verification error:', error);
        console.error('❌ Verification error details:', error.response?.data);
        setError(error.response?.data?.error || 'Email verification failed. Please try again.');
        setLoading(false);
      }
    };

    verifyEmail();
  }, [searchParams, navigate]);

  const handleGoToLogin = () => {
    navigate('/login');
  };

  const handleRetry = () => {
    setLoading(true);
    setError('');
    const token = searchParams.get('token');
    if (token) {
      // Retry the verification
      authAPI.verifyEmail(token)
        .then(response => {
          setMessage(response.data.message);
          setEmail(response.data.email);
          setLoading(false);
          setTimeout(() => {
            navigate('/login');
          }, 3000);
        })
        .catch(error => {
          setError(error.response?.data?.error || 'Email verification failed. Please try again.');
          setLoading(false);
        });
    }
  };

  return (
    <Container component="main" maxWidth="sm">
      <Box
        sx={{
          marginTop: 8,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
        }}
      >
        <Paper elevation={3} sx={{ padding: 4, width: '100%', textAlign: 'center' }}>
          <Typography component="h1" variant="h4" gutterBottom color="primary">
            Email Verification
          </Typography>

          {loading && (
            <Box sx={{ my: 3 }}>
              <CircularProgress size={60} />
              <Typography variant="body1" sx={{ mt: 2 }}>
                Verifying your email...
              </Typography>
            </Box>
          )}

          {message && (
            <Alert severity="success" sx={{ my: 2 }}>
              <Typography variant="h6" gutterBottom>
                Email Verified Successfully!
              </Typography>
              <Typography>
                {message}
              </Typography>
              {email && (
                <Typography variant="body2" sx={{ mt: 1 }}>
                  Verified email: <strong>{email}</strong>
                </Typography>
              )}
              <Typography variant="body2" sx={{ mt: 1, fontStyle: 'italic' }}>
                Redirecting to login page...
              </Typography>
            </Alert>
          )}

          {error && (
            <Alert severity="error" sx={{ my: 2 }}>
              <Typography variant="h6" gutterBottom>
                Verification Failed
              </Typography>
              <Typography>
                {error}
              </Typography>
              <Box sx={{ mt: 2 }}>
                <Button 
                  variant="outlined" 
                  onClick={handleRetry}
                  sx={{ mr: 1 }}
                >
                  Try Again
                </Button>
                <Button 
                  variant="contained" 
                  onClick={handleGoToLogin}
                >
                  Go to Login
                </Button>
              </Box>
            </Alert>
          )}

          {!loading && !error && !message && (
            <Button
              variant="contained"
              onClick={handleGoToLogin}
              sx={{ mt: 2 }}
              size="large"
            >
              Go to Login
            </Button>
          )}
        </Paper>
      </Box>
    </Container>
  );
};

export default VerifyEmail;
